import sys, json

# THE BRIEF OF AN OBJECT (GH #951), rendered here and nowhere else: `./push`
# (the text of a curator candidate) and `./tools` (`object_brief`) both ask
# this cell, so a model reads the same words in a push and in an answer.
#
# Pure and deterministic: the same row and the same facts give the same bytes.
# `<type>: <main name>`, then the filled slots in a fixed order (what, where, who,
# when, why, how) -- `who` only as `<n> people`, never a name and never a
# reference, because a brief travels to every turn of the row's round -- then
# every fact handed in, newest first as handed in, each whole.
# Nothing here reads a clock, a store or a round: who may read a brief is
# decided before it is rendered (`./tools`, `./push`).
#
# R-IG-1 (GH #1085): no length and no count of its own. Until objects 1.0.0
# the brief held 600 characters by whole parts, three facts of 200 characters
# each -- fixed numbers, whatever the window of the model reading it. Now a
# brief is whole, unless the request names a window (context `input_soft`,
# `recall_input_soft` its alias; a hop stamp here is no reader's): then it
# takes a tenth of it -- a tool result -- and a cut leaves its
# mark. A brief on its way to the curator (`./push`) is whole: the curator
# decides what fits the window it builds.
SLOTS = ("what", "where", "who", "when", "why", "how")
BRIEF_SHARE = 0.10
CUT_HINT = "budget of the window"


# >>> content-budget v1 (R-IG-1, GH #1085)
CHARS_PER_TOKEN = 3


def budget_chars(input_soft, share):
    """Characters a producer may hand a model whose usable window is
    `input_soft` tokens (the catalog row, cut by the curator), for a section
    that takes `share` of that window. None when no window is known: the
    producer then delivers its content whole."""
    try:
        soft = int(float(input_soft))
    except (TypeError, ValueError):
        return None
    if soft <= 0:
        return None
    return int(soft * share * CHARS_PER_TOKEN)


def clip(text, limit, hint="budget of the window"):
    """`text` whole when it fits `limit` (None: no limit); else its head and
    a mark naming what was shown, the total and how to get the rest."""
    text = "" if text is None else str(text)
    if limit is None or len(text) <= limit:
        return text
    limit = max(0, int(limit))
    return text[:limit] + "...[cut: %d of %d chars shown; %s]" % (
        limit, len(text), hint)
# <<< content-budget v1


def asked_soft(ctx, hop):
    """The window (tokens) the request names, or None."""
    for v in (ctx.get("input_soft"), ctx.get("recall_input_soft")):
        if budget_chars(v, 1.0) is not None:
            return v
    return None


def loads(v, default):
    if isinstance(v, str):
        try:
            x = json.loads(v)
        except Exception:
            return default
        return x if isinstance(x, type(default)) else default
    return v if isinstance(v, type(default)) else default


def one_line(v):
    return " ".join(str(v or "").split())


def main_name(row):
    aliases = [a for a in loads(row.get("aliases"), []) if isinstance(a, str) and a]
    return aliases[0] if aliases else str(row.get("id") or "")


def parts_of(row, facts):
    slots = loads(row.get("slots"), {})
    parts = ["%s: %s" % (one_line(row.get("type")) or "thing", one_line(main_name(row)))]
    for s in SLOTS:
        v = slots.get(s)
        if s == "who":
            n = len([x for x in v if isinstance(x, str) and x]) if isinstance(v, list) else 0
            if n:
                parts.append("who: %d people" % n)
        elif isinstance(v, str) and one_line(v):
            parts.append("%s: %s" % (s, one_line(v)))
    for f in [f for f in (facts if isinstance(facts, list) else []) if isinstance(f, str)]:
        t = one_line(f)
        if t:
            parts.append("fact: %s" % t)
    return parts


def render(row, facts, limit=None):
    """The brief, whole -- or cut to `limit` characters with its mark."""
    return clip("\n".join(parts_of(row if isinstance(row, dict) else {}, facts)),
                limit, CUT_HINT)


doc = json.load(sys.stdin)
d = doc.get("body") or {}
hop = ((doc.get("envelope") or {}).get("header") or {}).get("hop") or {}
ctx = ((doc.get("envelope") or {}).get("header") or {}).get("context") or {}
lane = str(hop.get("route") or "")
if lane != "brief_render":
    sys.stderr.write("objects/brief: unknown lane %r -- dropped\n" % lane)
    sys.stdout.write("[]")
    sys.exit(0)
row = d.get("row") if isinstance(d.get("row"), dict) else {}
sys.stdout.write(json.dumps([{
    "header": {"route": "rendered", "reply_cell": str(hop.get("reply_cell") or "")},
    "text": render(row, d.get("facts"), budget_chars(asked_soft(ctx, hop), BRIEF_SHARE)),
    "carry": d.get("carry") if isinstance(d.get("carry"), dict) else {},
    "messages": []}], ensure_ascii=False))
